import * as THREE from "three";
import { OrbitControls } from "three/addons/controls/OrbitControls.js";

// ---------- dimensions (meters) ----------
const LEG_LEN   = 0.45;     // 45 cm legs
const LEG_R     = 0.011;    // leg radius (~2.2cm dowel)
const ALPHA     = THREE.MathUtils.degToRad(20); // splay angle from vertical
const FRAME_GAP = 0.30;     // distance between the two X-frames (seat depth)
const BOLT_R    = 0.014;
const SAG       = 0.028;    // canvas droop

