const pivotY = (LEG_LEN / 2) * Math.cos(ALPHA);
const dx = (LEG_LEN / 2) * Math.sin(ALPHA);
const dy = (LEG_LEN / 2) * Math.cos(ALPHA);

// top/bottom endpoints of the two crossing legs (front = +x, back = -x)
const topFront = new THREE.Vector3( dx, pivotY + dy, 0);
const botBack  = new THREE.Vector3(-dx, pivotY - dy, 0);
const topBack  = new THREE.Vector3(-dx, pivotY + dy, 0);
const botFront = new THREE.Vector3( dx, pivotY - dy, 0);

// ---------- scene ----------
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1b1e22);
scene.fog = new THREE.Fog(0x1b1e22, 3, 9);

const camera = new THREE.PerspectiveCamera(40, innerWidth / innerHeight, 0.01, 50);
camera.position.set(1.1, 0.75, 1.35);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, pivotY, 0);
controls.enableDamping = true;
controls.minDistance = 0.6;
controls.maxDistance = 4;
controls.maxPolarAngle = Math.PI * 0.49;

// ---------- lights ----------
scene.add(new THREE.HemisphereLight(0xbfd4ff, 0x2b241d, 0.6));
const key = new THREE.DirectionalLight(0xfff2df, 2.2);
key.position.set(1.6, 2.4, 1.2);
key.castShadow = true;
key.shadow.mapSize.set(2048, 2048);
key.shadow.camera.near = 0.5;
key.shadow.camera.far = 8;
key.shadow.camera.left = -1.2;
key.shadow.camera.right = 1.2;
key.shadow.camera.top = 1.2;
key.shadow.camera.bottom = -1.2;
key.shadow.bias = -0.0015;
scene.add(key);
const fill = new THREE.DirectionalLight(0x9fc7ff, 0.4);
fill.position.set(-1.5, 1, -1.2);
scene.add(fill);

// ---------- ground ----------
const ground = new THREE.Mesh(
  new THREE.CircleGeometry(3, 64),
  new THREE.MeshStandardMaterial({ color: 0x2a2d31, roughness: 1 })
);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);
const grid = new THREE.GridHelper(3, 30, 0x444850, 0x33363b);
grid.position.y = 0.0005;
scene.add(grid);

// ---------- materials ----------
const woodMat = new THREE.MeshStandardMaterial({ color: 0xb07d4f, roughness: 0.55, metalness: 0.05 });
const boltMat = new THREE.MeshStandardMaterial({ color: 0x4a4d52, roughness: 0.35, metalness: 0.85 });
const canvasMat = new THREE.MeshStandardMaterial({
  color: 0xc8b78a, roughness: 0.9, metalness: 0.0, side: THREE.DoubleSide
});

// ---------- helper: a leg cylinder between two points ----------
function makeLeg(p1, p2) {
  const dir = new THREE.Vector3().subVectors(p2, p1);
  const len = dir.length();
  const geo = new THREE.CylinderGeometry(LEG_R, LEG_R, len, 20);
  const mesh = new THREE.Mesh(geo, woodMat);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  const mid = new THREE.Vector3().addVectors(p1, p2).multiplyScalar(0.5);
  mesh.position.copy(mid);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  return mesh;
}

// ---------- build one X-frame at a given z offset ----------
function buildFrame(z) {
  const group = new THREE.Group();
  const shift = (p) => new THREE.Vector3(p.x, p.y, z);
  group.add(makeLeg(shift(botFront), shift(topBack)));  // leg A: front-bottom to back-top
  group.add(makeLeg(shift(botBack),  shift(topFront)));  // leg B: back-bottom to front-top
  return group;
}

const frameZ = FRAME_GAP / 2;
scene.add(buildFrame(-frameZ));
scene.add(buildFrame(frameZ));

// pivot bolt spanning both frames
const boltLen = FRAME_GAP + 0.05;
const bolt = new THREE.Mesh(new THREE.CylinderGeometry(BOLT_R, BOLT_R, boltLen, 20), boltMat);
bolt.rotation.x = Math.PI / 2;
bolt.position.set(0, pivotY, 0);
bolt.castShadow = true;
scene.add(bolt);
// bolt head + nut caps
[-1, 1].forEach((s) => {
  const cap = new THREE.Mesh(new THREE.CylinderGeometry(BOLT_R * 1.8, BOLT_R * 1.8, 0.006, 6), boltMat);
  cap.rotation.x = Math.PI / 2;
  cap.position.set(0, pivotY, s * (boltLen / 2 - 0.003));
  scene.add(cap);
});

// ---------- canvas seat strap (front top -> back top, sagging) ----------
function buildSeat() {
  const segX = 24, segZ = 2;
  const geo = new THREE.PlaneGeometry(1, FRAME_GAP + 0.06, segX, segZ);
  geo.rotateX(-Math.PI / 2); // lay flat, plane's local X/Y -> world X/Z

  const pos = geo.attributes.position;
  const x0 = topFront.x, x1 = topBack.x; // spans front-top to back-top
  const yTop = topFront.y; // topFront.y === topBack.y by symmetry

  for (let i = 0; i < pos.count; i++) {
    const u = (pos.getX(i) + 0.5); // 0..1 along the plane's original X (now width dir)
    const worldX = THREE.MathUtils.lerp(x0, x1, u);
    const sag = Math.sin(u * Math.PI) * SAG; // droop most in the middle
    pos.setX(i, worldX);
    pos.setY(i, yTop - sag);
    // z (pos.getZ) already spans -FRAME_GAP/2-0.03 .. +FRAME_GAP/2+0.03, leave as-is
  }
  geo.computeVertexNormals();

  const mesh = new THREE.Mesh(geo, canvasMat);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}
scene.add(buildSeat());

// ---------- animate ----------
function onResize() {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
}
window.addEventListener("resize", onResize);

renderer.setAnimationLoop(() => {
  controls.update();
  renderer.render(scene, camera);
});
</script>
</body>
</html>
