```openscad
// Wall-mounted bike hook
// Units: mm

// --- Parameters ---
plate_w        = 60;   // mounting plate width
plate_h        = 80;   // mounting plate height
plate_t        = 8;    // mounting plate thickness
hole_d         = 5;    // screw hole diameter
hole_inset     = 10;   // distance of screw holes from plate edges

hook_d         = 22;   // diameter of hook arm (round bar)
hook_out       = 70;   // how far the hook extends from wall
hook_up        = 55;   // height of curved rise
hook_radius    = 35;   // bend radius of the hook curve
tip_len        = 40;   // length of upturned tip that catches the wheel/frame

$fn = 64;

module rounded_plate() {
    difference() {
        // rounded-rect backplate
        hull() {
            for (x = [hole_inset, plate_w - hole_inset])
                for (y = [hole_inset, plate_h - hole_inset])
                    translate([x, y, 0])
                        cylinder(h = plate_t, r = 6);
        }
        // screw holes
        for (x = [hole_inset, plate_w - hole_inset])
            for (y = [hole_inset, plate_h - hole_inset])
                translate([x, y, -1])
                    cylinder(h = plate_t + 2, d = hole_d);
    }
}

module hook_arm() {
    // Build the arm as a path of cylinders/spheres swept via hull(),
    // going: out from wall -> curve upward -> short upturned tip.

    // straight section out from the wall
    hull() {
        translate([plate_w/2, plate_h/2, plate_t])
            sphere(d = hook_d);
        translate([plate_w/2, plate_h/2, plate_t + hook_out])
            sphere(d = hook_d);
    }

    // curved rise (approximated with segments)
    seg = 12;
    for (i = [0 : seg - 1]) {
        a1 = 90 * i / seg;
        a2 = 90 * (i + 1) / seg;
        p1 = [plate_w/2 + hook_radius * sin(a1),
              plate_h/2,
              plate_t + hook_out + hook_radius - hook_radius * cos(a1)];
        p2 = [plate_w/2 + hook_radius * sin(a2),
              plate_h/2,
              plate_t + hook_out + hook_radius - hook_radius * cos(a2)];
        hull() {
            translate(p1) sphere(d = hook_d);
            translate(p2) sphere(d = hook_d);
        }
    }

    // upturned tip that keeps the wheel/frame from sliding off
    tip_base = [plate_w/2 + hook_radius,
                plate_h/2,
                plate_t + hook_out + hook_radius];
    hull() {
        translate(tip_base) sphere(d = hook_d);
        translate([tip_base[0] - tip_len * 0.3,
                    tip_base[1],
                    tip_base[2] + tip_len])
            sphere(d = hook_d);
    }
}

module gusset() {
    // triangular support brace between plate and arm for strength
    hull() {
        translate([plate_w/2, plate_h/2, plate_t])
            sphere(d = hook_d * 0.8);
        translate([plate_w/2, plate_h/2, plate_t + hook_out * 0.5])
            sphere(d = hook_d * 0.8);
        translate([plate_w/2, plate_h/2 - 18, plate_t])
            sphere(d = hook_d * 0.8);
    }
}

module bike_hook() {
    rounded_plate();
    hook_arm();
    gusset();
}

bike_hook();
```

Adjust `hook_out`, `hook_up`/`hook_radius`, and `hook_d` to fit your wheel/frame thickness. The gusset gives it extra strength at the wall joint — print with the plate flat on the bed and the arm supported, or orient at an angle for a stronger layer line direction along the load.

```openscad
// Wall-mounted bike hook
// Units: mm

$fn = 60;

// ---- Parameters ----
plate_w      = 60;
plate_h      = 60;
plate_t      = 8;

hole_d       = 5;      // screw hole diameter
hole_inset   = 8;      // distance of holes from plate edges

hook_d       = 22;     // diameter of hook tube
hook_len     = 90;     // straight length out from wall
hook_radius  = 35;     // bend radius
hook_angle   = 200;    // degrees of curve (>180 so bike tire can't slip off)

lip_len      = 15;     // little upturned tip at the end to stop slipping

module mounting_plate() {
    difference() {
        cube([plate_w, plate_h, plate_t], center = false);

        // Screw holes near each corner
        for (x = [hole_inset, plate_w - hole_inset])
            for (y = [hole_inset, plate_h - hole_inset])
                translate([x, y, -1])
                    cylinder(d = hole_d, h = plate_t + 2);
    }
}

module hook_arm() {
    // Straight section coming off the wall
    rotate([0, 90, 0])
        cylinder(d = hook_d, h = hook_len);

    // Curved section at the end of the straight arm
    translate([hook_len, 0, 0])
        rotate([90, 0, 0])
            rotate_extrude(angle = hook_angle, convexity = 10)
                translate([hook_radius, 0, 0])
                    circle(d = hook_d);

    // Small upturned lip at the very tip so things don't slide off
    translate([
        hook_len + hook_radius * (1 - cos(hook_angle)),
        0,
        hook_radius * sin(hook_angle) * -1
    ])
        rotate([0, hook_angle, 0])
            rotate([0, 90, 0])
                cylinder(d = hook_d, h = lip_len);
}

module bike_hook() {
    union() {
        // Plate centered so the hook comes out of its middle
        translate([-plate_w/2, -plate_h/2, 0])
            mounting_plate();

        // Hook starts at plate face, centered
        translate([0, 0, plate_t])
            hook_arm();
    }
}

bike_hook();
```

This gives you a square wall plate with 4 mounting screw holes, and a curved hook (over 180° of bend so the bike/wheel won't slip off) extending from the plate with an upturned lip at the tip. Adjust `hook_d` for thicker/thinner tube stock, `hook_len`/`hook_radius` for reach, and `hook_angle` for how "captured" you want the wheel to be.

